let dados = { ...$('Dados').item.json };

if ($('Adicionar transcricao do audio a mensagem').isExecuted) {
  dados = { ...$('Adicionar transcricao do audio a mensagem').item.json };
} else if ($('Adicionar analise visual a mensagem').isExecuted) {
  dados = { ...$('Adicionar analise visual a mensagem').item.json };
}

const marker = $('Marcar timestamp desta mensagem').item.json;
const generationData = $('Incrementar geração da conversa').item.json || {};
const generation = Number(Object.values(generationData)[0] || 0);
const sourceType = dados.audioProcessed ? 'audio' : dados.imageProcessed ? 'image' : 'text';

const bufferItem = {
  version: 2,
  messageId: String(dados.rawMessageId || dados.payload_id || marker.bufferToken || ''),
  replyToMessageId: String(dados.replyToMessageId || ''),
  token: String(marker.bufferToken || ''),
  generation,
  sourceType,
  sentAt: String(dados.TimeStamp || ''),
  receivedAtMs: Number(marker.bufferTimestamp || 0),
  status: 'ready',
  message: String(dados.message || '').trim(),
};

return [{
  json: {
    bufferItemJson: JSON.stringify(bufferItem),
    bufferToken: bufferItem.token,
    bufferTimestamp: String(bufferItem.receivedAtMs),
    generation,
  },
}];

const rawMap = $('Ler mensagens do contato').first().json || {};
const cutoff = Number($json.value || 0);
const nowMs = Date.now();
const maxPendingMs = 90000;

function parseItem(value) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(String(value));
  } catch (error) {
    return null;
  }
}

const parsed = Object.values(rawMap).map(parseItem).filter(Boolean);
const unique = new Map();

for (const item of parsed) {
  const identity = String(item.messageId || item.token || '');
  if (!identity) continue;
  const previous = unique.get(identity);
  if (!previous || String(item.status || '') === 'ready') unique.set(identity, item);
}

let messages = [...unique.values()]
  .filter((item) => Number(item.receivedAtMs || 0) > cutoff);

let pendingCount = 0;
messages = messages.map((item) => {
  if (String(item.status || '') !== 'processing') return item;
  const ageMs = Math.max(0, nowMs - Number(item.receivedAtMs || 0));
  if (ageMs < maxPendingMs) {
    pendingCount += 1;
    return item;
  }

  const sourceType = String(item.sourceType || 'text');
  const fallback = sourceType === 'image'
    ? '[ANÁLISE VISUAL INDISPONÍVEL]\nA imagem foi recebida, mas não foi possível obter uma descrição confiável.'
    : sourceType === 'audio'
      ? '[TRANSCRIÇÃO DO ÁUDIO INDISPONÍVEL]\nO áudio foi recebido, mas não foi possível obter uma transcrição confiável.'
      : String(item.message || '');

  const original = String(item.message || '').trim();
  return {
    ...item,
    status: 'ready-timeout',
    message: [original, fallback].filter(Boolean).join('\n\n'),
  };
});

function sentAtMs(item) {
  const parsedDate = Date.parse(String(item.sentAt || ''));
  return Number.isFinite(parsedDate) ? parsedDate : Number(item.receivedAtMs || 0);
}

messages.sort((a, b) => {
  const bySentAt = sentAtMs(a) - sentAtMs(b);
  if (bySentAt !== 0) return bySentAt;
  return Number(a.receivedAtMs || 0) - Number(b.receivedAtMs || 0);
});

const dados = { ...$('Dados').item.json };
const labels = { text: 'TEXTO', image: 'IMAGEM', audio: 'ÁUDIO' };
const readyMessages = messages.filter((item) => String(item.status || '') !== 'processing');

if (readyMessages.length > 1) {
  const blocks = readyMessages.map((item, index) => {
    const label = labels[String(item.sourceType || 'text')] || 'MENSAGEM';
    return '[MENSAGEM ' + (index + 1) + ' — ' + label + ']\n' + String(item.message || '').trim();
  });
  dados.message = '[ENTRADA AGRUPADA DO MESMO CLIENTE]\nInterprete todas as mensagens abaixo como partes da mesma conversa, na ordem apresentada.\n\n' + blocks.join('\n\n');
} else if (readyMessages.length === 1) {
  dados.message = String(readyMessages[0].message || dados.message || '').trim();
}

dados.bufferPendingCount = pendingCount;
dados.bufferItemCount = messages.length;
dados.bufferHasImage = messages.some((item) => item.sourceType === 'image');
dados.bufferHasAudio = messages.some((item) => item.sourceType === 'audio');
dados.bufferMaxReceivedAtMs = messages.reduce(
  (maximum, item) => Math.max(maximum, Number(item.receivedAtMs || 0)),
  Number($('Marcar timestamp desta mensagem').item.json.bufferTimestamp || 0),
);
dados.bufferGeneration = Number(Object.values($('Incrementar geração da conversa').item.json || {})[0] || 0);

return [{ json: dados }];

const item = { ...$json };
const source = $('Dados').item.json;
const timezone = source.timezone || 'America/Sao_Paulo';
const schedules = source.businessHours || {};
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
  timeZone: timezone, weekday: 'long', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
}).formatToParts(new Date()).map((part) => [part.type, part.value]));
const day = String(parts.weekday || '').toLowerCase();
const schedule = schedules[day] || { enabled: false, opens_at: '00:00', closes_at: '00:00' };
const currentMinutes = Number(parts.hour) * 60 + Number(parts.minute);
const toMinutes = (value) => { const [h, m] = String(value || '00:00').split(':').map(Number); return h * 60 + m; };
const opens = toMinutes(schedule.opens_at);
const closes = toMinutes(schedule.closes_at);
const openNow = schedule.enabled === true && currentMinutes >= opens && currentMinutes < closes;
item.businessOpenNow = openNow;
item.currentDate = `${parts.day}/${parts.month}/${parts.year}`;
item.currentTime = `${parts.hour}:${parts.minute}`;
item.currentWeekday = day;
item.businessHoursToday = schedule.enabled ? `${schedule.opens_at} às ${schedule.closes_at}` : 'fechado';
const normalized = String(item.message || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
item.perguntaHorarioAtual = /\b(abert|fechad|funciona|horario|atendendo)\w*/.test(normalized) && normalized.length < 180;
if (item.perguntaHorarioAtual) {
  item.respostaHorario = openNow
    ? `Sim, estamos atendendo agora. O horário de hoje é ${item.businessHoursToday}.`
    : `No momento estamos fechados. O horário de hoje é ${item.businessHoursToday}.`;
}
return [{ json: item }];

const base = { ...$('Dados').item.json };
const analysis = $input.first().json || {};

function textFrom(value) {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(textFrom).filter(Boolean).join('\n').trim();
  if (!value || typeof value !== 'object' || value.error) return '';
  const preferredKeys = ['text', 'content', 'output', 'result', 'response', 'parts', 'candidates'];
  for (const key of preferredKeys) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      const found = textFrom(value[key]);
      if (found) return found;
    }
  }
  return '';
}

const visualText = textFrom(analysis);
const originalMessage = String(base.message || '').trim();
const visualBlock = visualText
  ? '[ANÁLISE VISUAL DA IMAGEM]\n' + visualText
  : '[ANÁLISE VISUAL INDISPONÍVEL]\nA imagem foi recebida, mas não foi possível obter uma descrição confiável.';

base.message = [originalMessage, visualBlock].filter(Boolean).join('\n\n');
base.imageAnalysis = visualText;
base.imageProcessed = true;
base.mediaAnalyzed = Boolean(visualText);
base.hasMedia = false;
base.mediaType = '';
base.mediaUrl = '';

return [{ json: base }];

const base = { ...$('Dados').item.json };
const transcription = $input.first().json || {};

function textFrom(value) {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(textFrom).filter(Boolean).join('\n').trim();
  if (!value || typeof value !== 'object' || value.error) return '';
  const preferredKeys = ['text', 'transcript', 'transcription', 'content', 'output', 'result', 'response', 'parts', 'candidates'];
  for (const key of preferredKeys) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      const found = textFrom(value[key]);
      if (found) return found;
    }
  }
  return '';
}

const audioText = textFrom(transcription);
base.message = audioText
  ? '[TRANSCRIÇÃO DO ÁUDIO]\n' + audioText
  : '[TRANSCRIÇÃO DO ÁUDIO INDISPONÍVEL]\nO áudio foi recebido, mas não foi possível obter uma transcrição confiável.';
base.audioTranscription = audioText;
base.audioProcessed = true;
base.mediaAnalyzed = Boolean(audioText);
base.isAudio = false;
base.hasMedia = false;
base.mediaType = '';
base.mediaUrl = '';

return [{ json: base }];

const result = { ...$json };
let output = String(result.output || '').trim().replace(/\s*\n+\s*/g, ' ');
if (!output) output = $('Dados').item.json.humanHandoffMessage || 'Vou chamar uma pessoa da nossa equipe para continuar com você.';
if (output.length > 4096) output = output.slice(0, 4093) + '...';
result.output = output;
return [{ json: result }];
